<?php require '../config.php';if(!admin()){header('Location: login.php');exit;}$pdo=db();$msg='';$err='';if(isset($_GET['stop'])){$s=$pdo->prepare("UPDATE tours SET TrangThai='ngung' WHERE MaTour=?");$s->execute([(int)$_GET['stop']]);$msg='Đã ngừng mở bán tour.';}if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$place=(int)($_POST['place']??0);$price=(float)($_POST['price']??0);$days=(int)($_POST['days']??0);$nights=(int)($_POST['nights']??0);$desc=trim($_POST['desc']??'');$img=trim($_POST['img']??'');if(!$name||!$place||$price<=0||$days<1)$err='Vui lòng nhập dữ liệu hợp lệ.';else{if($id){$s=$pdo->prepare("UPDATE tours SET TenTour=?,MaDiaDiem=?,GiaTour=?,SoNgay=?,SoDem=?,MoTa=?,AnhDaiDien=?,TrangThai='dang_mo' WHERE MaTour=?");$s->execute([$name,$place,$price,$days,$nights,$desc,$img,$id]);$msg='Đã sửa tour.';}else{$s=$pdo->prepare("INSERT INTO tours(TenTour,MaDiaDiem,GiaTour,SoNgay,SoDem,MoTa,AnhDaiDien) VALUES(?,?,?,?,?,?,?)");$s->execute([$name,$place,$price,$days,$nights,$desc,$img]);$msg='Đã thêm tour.';}}}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM tours WHERE MaTour=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$places=$pdo->query("SELECT * FROM diadiem")->fetchAll();$tours=$pdo->query("SELECT t.*,d.TenDiaDiem FROM tours t JOIN diadiem d ON d.MaDiaDiem=t.MaDiaDiem ORDER BY t.MaTour DESC")->fetchAll();$orders=$pdo->query("SELECT b.*,c.HoTen,t.TenTour FROM dattour b JOIN khachhang c ON c.MaKhachHang=b.MaKhachHang JOIN tours t ON t.MaTour=b.MaTour ORDER BY b.MaDatTour DESC LIMIT 30")->fetchAll();$title='Quản trị — TourVela';require '../includes/header.php';?><section class="admin section"><div class="sectionhead"><div><div class="eyebrow">● BẢNG ĐIỀU KHIỂN</div><h2>Quản lý <em>TourVela.</em></h2></div><a class="btn dark" href="logout.php">Đăng xuất ↗</a></div><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><?php if($err):?><div class="notice"><?=$err?></div><?php endif;?><div class="adminlayout"><div class="booking"><h3><?=$edit?'Sửa tour':'Thêm tour mới'?></h3><form method="post" class="form"><input type="hidden" name="id" value="<?=(int)($edit['MaTour']??0)?>"><label>Tên tour<input name="name" required value="<?=e($edit['TenTour']??'')?>"></label><label>Điểm đến<select name="place"><?php foreach($places as $p):?><option value="<?=$p['MaDiaDiem']?>" <?=($edit['MaDiaDiem']??0)==$p['MaDiaDiem']?'selected':''?>><?=e($p['TenDiaDiem'])?></option><?php endforeach;?></select></label><div class="twocol"><label>Giá VNĐ<input type="number" name="price" required value="<?=e($edit['GiaTour']??'')?>"></label><label>Số ngày<input type="number" name="days" value="<?=e($edit['SoNgay']??3)?>"></label></div><label>Số đêm<input type="number" name="nights" value="<?=e($edit['SoDem']??2)?>"></label><label>URL ảnh<input name="img" value="<?=e($edit['AnhDaiDien']??'')?>"></label><label>Mô tả<textarea name="desc"><?=e($edit['MoTa']??'')?></textarea></label><button class="btn orange full">Lưu tour ↗</button><?php if($edit):?><a href="index.php">Huỷ sửa</a><?php endif;?></form></div><div class="booking tablewrap"><h3>Danh sách tour</h3><table><tr><th>Tour</th><th>Giá</th><th>Trạng thái</th><th>Thao tác</th></tr><?php foreach($tours as $t):?><tr><td><?=e($t['TenTour'])?><small><?=e($t['TenDiaDiem'])?></small></td><td><?=money($t['GiaTour'])?></td><td><?=e($t['TrangThai'])?></td><td><a href="?edit=<?=$t['MaTour']?>">Sửa</a> · <a onclick="return confirm('Ngừng mở bán tour?')" href="?stop=<?=$t['MaTour']?>">Ngừng</a></td></tr><?php endforeach;?></table></div></div><div class="booking tablewrap ordertable"><h3>Đơn đặt tour gần đây</h3><table><tr><th>Mã</th><th>Khách</th><th>Tour</th><th>Khởi hành</th><th>Số người</th><th>Tổng tiền</th><th>Trạng thái</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['MaDatTour']?></td><td><?=e($o['HoTen'])?></td><td><?=e($o['TenTour'])?></td><td><?=$o['NgayKhoiHanh']?></td><td><?=$o['SoNguoi']?></td><td><?=money($o['TongTien'])?></td><td><?=e($o['TrangThai'])?></td></tr><?php endforeach;?></table></div></section><?php require '../includes/footer.php';?>
